let scenarioIndex=0,stageIndex=0,scenarioHistory=[],scenarioSeverity=0,scenarioAnswered=false;
const balancedSlots=n=>{const a=shuffle(Array.from({length:n},(_,i)=>i%3));for(let i=2;i<a.length;i++){if(a[i]===a[i-1]&&a[i]===a[i-2]){const k=a.findIndex((v,j)=>j>i&&v!==a[i]);if(k>=0)[a[i],a[k]]=[a[k],a[i]];}}return a};
let caseSlots=balancedSlots(4);
function renderCarry(){const x=$('#scenarioCarry');if(!scenarioHistory.length){x.textContent='Condição inicial: sistema sem desvios acumulados.';return;}const bad=scenarioHistory.filter(z=>!z.ok).length;x.textContent=bad?`Consequência acumulada: ${bad} decisão(ões) com diagnóstico incompleto. A interpretação seguinte considera maior incerteza, demora e necessidade de reconfirmação.`:'Consequência acumulada: decisões anteriores reduziram incertezas; prossiga acompanhando todas as tendências e permissivos.';x.classList.toggle('at-risk',!!bad)}
function renderScenario(){const c=cases[scenarioIndex];const s=c.stages[stageIndex];scenarioAnswered=false;$('#caseMeta').textContent=`${c.name.toUpperCase()} · DECISÃO ${stageIndex+1} / ${c.stages.length}`;$('#caseTitle').textContent=s.title;$('#caseNarrative').textContent=(scenarioSeverity?`DESDOBRAMENTO DO SEU HISTÓRICO — ${scenarioSeverity} decisão(ões) a revisar. Informações ficaram menos confiáveis e a coordenação precisará compensar isso.\n\n`:'')+s.narrative;$('#caseTelemetry').innerHTML=s.telemetry.map(x=>`<span>${x}</span>`).join('')+(scenarioSeverity?'<span class="telemetry-risk">Estado acumulado: confirmar diagnósticos pendentes</span>':'');$('#caseQuestion').textContent=s.question;$('#caseFeedback').hidden=true;$('#nextCase').hidden=true;let order=shuffle([0,1,2]);const desired=caseSlots[stageIndex];const current=order.indexOf(s.correct);[order[desired],order[current]]=[order[current],order[desired]];$('#caseChoices').innerHTML='';for(const i of order){const b=document.createElement('button');b.className='choice';b.textContent=s.choices[i];b.addEventListener('click',()=>answerScenario(i,b));$('#caseChoices').append(b)}renderScenarioHistory();renderCarry()}
function answerScenario(idx,node){if(scenarioAnswered)return;scenarioAnswered=true;const s=cases[scenarioIndex].stages[stageIndex];const ok=idx===s.correct;if(!ok)scenarioSeverity++;$$('#caseChoices .choice').forEach(x=>{x.disabled=true;if(x===node)x.classList.add(ok?'good':'bad')});$('#caseFeedback').className='feedback'+(ok?'':' bad');$('#caseFeedback').innerHTML=`<b>${ok?'Interpretação consistente':'Decisão exige revisão'}</b><div>${s.feedback}</div>${!ok?'<div>Esta decisão aumenta a criticidade acumulada do cenário de treinamento.</div>':''}`;$('#caseFeedback').hidden=false;scenarioHistory.push({title:s.title,choice:s.choices[idx],ok});$('#nextCase').hidden=false;renderCarry();$('#nextCase').textContent=stageIndex===cases[scenarioIndex].stages.length-1?'Ver resultado do caso →':'Próxima decisão →';renderScenarioHistory();renderCarry()}
function renderScenarioHistory(){$('#caseHistory').innerHTML=scenarioHistory.length?scenarioHistory.map((o,i)=>`<div class="history-entry"><span>ETAPA ${i+1} · ${o.ok?'CRITÉRIO ATENDIDO':'REAVALIAR'}</span><br/><strong>${o.title}</strong><br/>${o.choice}</div>`).join(''):'<p>As escolhas serão registradas aqui.</p>'}
$('#nextCase').addEventListener('click',()=>{const c=cases[scenarioIndex];if(stageIndex<c.stages.length-1){stageIndex++;renderScenario()}else{scenarioAnswered=true;$('#caseTitle').textContent='Caso concluído · balanço da tomada de decisão';$('#caseNarrative').textContent=scenarioSeverity===0?'Você identificou as principais relações entre circulação, balanço térmico e proteção dos equipamentos.':'Revise as decisões marcadas para compreender os riscos de diagnósticos incompletos e atrasos.';$('#caseTelemetry').innerHTML=`<span>Decisões concluídas: ${c.stages.length}</span><span>Decisões a revisar: ${scenarioSeverity}</span>`;$('#caseQuestion').textContent='Use “Reiniciar caso” ou escolha outro cenário para praticar.';$('#caseChoices').innerHTML='';$('#caseFeedback').hidden=true;$('#nextCase').hidden=true}});
function resetCase(){stageIndex=0;scenarioHistory=[];scenarioSeverity=0;caseSlots=balancedSlots(cases[scenarioIndex].stages.length);renderScenario()}$('#resetScenario').addEventListener('click',resetCase);$$('[data-case]').forEach(b=>b.addEventListener('click',()=>{scenarioIndex=+b.dataset.case;$$('[data-case]').forEach(x=>x.classList.toggle('active',x===b));resetCase()}));renderScenario();
const questions=[
{q:'A reserva J-3911A apresenta rotação, mas os FIC-39162 e FIC-39163 não recuperam. Qual hipótese investigar antes de declarar a recuperação?',a:['Há giro da bomba, porém o caminho hidráulico pode continuar sem vazão útil.', 'Há indicação de giro, então a elevação térmica deve ser apenas transitória.', 'Há baixa vazão de retorno, mas a pressão de descarga elimina falha hidráulica.'],ok:0,why:'Giro, pressão e vazão são grandezas diferentes; conferir linha, sucção, válvulas e vazões.'},
{q:'Após perda do refluxo, TIC-39186 sobe enquanto a carga continua estável. Qual interpretação energética é coerente?',a:['A capacidade de lavagem diminuiu, porém a retirada de calor tende a aumentar.', 'A energia do efluente permanece e a remoção via borra foi reduzida.', 'A entrada de calor diminui proporcionalmente à vazão do circuito de borra.'],ok:1,why:'Com vapores quentes chegando e menor remoção pela borra, a temperatura tende a subir.'},
{q:'Por que acompanhar TIC-39186 e TIC-39180 simultaneamente?',a:['Porque cada ponto possui massa, resposta térmica e mecanismos de risco diferentes.', 'Porque os dois registros podem acompanhar uma mesma perturbação no circuito térmico.', 'Porque apenas uma dessas medições varia depois que a J-3911 deixa de operar.'],ok:0,why:'Zona de flash e fundo apresentam dinâmica e riscos de coqueamento/lavagem distintos.'},
{q:'Média dos TI-39186 em 435 °C e um termopar em 457 °C: qual interpretação é tecnicamente consistente?',a:['A média elimina a importância dos termopares individuais mesmo se um deles estiver acima da referência.', 'O maior TI aponta que a PV média está em 457 °C, se todos os canais são válidos.', 'Uma região quente ou um desvio instrumental podem estar parcialmente ocultos na média.'],ok:2,why:'É necessário distinguir ponto quente real, dispersão térmica e falha do instrumento.'},
{q:'HV-39157 indicada em 90%, porém TIC-39186 ainda acelera. O que esse conjunto permite concluir?',a:['A abertura requerida foi emitida, mas a capacidade de resfriar não está comprovada.', 'Uma abertura de 90% indica que há vazão e sub-resfriamento suficientes na torre.', 'A posição de 90% garante que o nível do fundo esteja protegido durante toda a falha.'],ok:0,why:'Comando não garante vazão, disponibilidade, qualidade térmica nem eficácia.'},
{q:'O que tende a aumentar o risco de coqueamento do fundo, mesmo com nível dentro da faixa?',a:['Uma renovação mais intensa do inventário, mantida a carga térmica original no fundo.', 'Circulação insuficiente, pontos quentes e maior exposição da fração pesada.', 'Elevada capacidade de resfriamento e menor presença de finos arrastados.'],ok:1,why:'Coqueamento depende de temperatura, residência, composição e circulação, não apenas nível.'},
{q:'O critério 440 °C por 5 min deve ser interpretado no CIC como:',a:['Um tempo de espera a cumprir antes de avaliar a necessidade de proteção.', 'Uma referência equivalente à maior leitura dos cinco sensores na região de flash.', 'Uma referência que deve ser associada à tendência, confiabilidade e procedimento vigente.'],ok:2,why:'Os tempos da imagem não autorizam exposição deliberada ou postergação de decisões.'},
{q:'Quando a temperatura cai abaixo do valor de referência após exposição térmica, o que significa o contador do simulador?',a:['A exposição consecutiva reinicia neste modelo; o histórico do evento permanece relevante.', 'O risco térmico é revertido quando o temporizador volta a zero no painel de controle.', 'O tempo de exposição deve continuar aumentando mesmo se a temperatura recuar.'],ok:0,why:'O contador modela exposição consecutiva, não dano acumulado nem lógica real de trip.'},
{q:'Com a retirada de carga fresca após falha da borra, qual resposta de processo é esperada?',a:['A circulação de borra é restabelecida sem depender das condições das bombas.', 'A geração de efluente craqueado tende a reduzir, alterando gradualmente o calor recebido.', 'O aumento de capacidade do refluxo de borra decorre diretamente da carga menor.'],ok:1,why:'Redução da carga altera o balanço do conversor e a geração de vapores, não cria fluxo de borra.'},
{q:'Após trip parcial, por que é inadequado tratar o fechamento das slide valves como operação isolada?',a:['Porque o evento envolve apenas a posição das válvulas e não as pressões dos vasos.', 'Porque os inventários de catalisador tornam-se irrelevantes após fechar as slides.', 'Porque pressões diferenciais, circulação de catalisador e condições de selagem importam.'],ok:2,why:'A sequência real requer causa e efeito e controle de pressão/inventários.'},
{q:'Qual aspecto da curva H bomba versus H sistema ajuda a interpretar vazão nula com acionamento ligado?',a:['A operação depende da interseção das curvas e pode ser anulada por problemas hidráulicos.', 'A rotação nominal assegura a vazão contratual independentemente do circuito conectado.', 'O diferencial elevado de pressão confirma que os dois retornos da fracionadora recebem borra em quantidade nominal.'],ok:0,why:'Perdas, obstruções, cavitação e alinhamentos deslocam o ponto de operação.'},
{q:'A redução do retorno superior FIC-39162 afeta primeiramente qual conjunto de funções?',a:['Controle do nível do tambor de topo e condensação completa do gás úmido.', 'Lavagem de partículas, contato gás-líquido e remoção de calor na seção de chicanas.', 'Retorno dos gases de regeneração e controle da entrada de ar no catcooler.'],ok:1,why:'O FIC-39162 regula o circuito superior de refluxo de borra à E-3901.'},
{q:'A redução de FIC-39163 prejudica de forma especial:',a:['A retirada de calor na região de contato dos vapores com refluxo superior.', 'A redução automática da temperatura do óleo decantado após o C-3929.', 'A homogeneização e o sub-resfriamento do líquido acumulado no fundo.'],ok:2,why:'O Manual descreve o retorno inferior como proteção do inventário pesado.'},
{q:'O fundo indica elevação de nível depois da falha J-3911A/B. Qual análise é necessária?',a:['Comparar entradas, saídas, vaporização e possíveis rotas de retirada do inventário.', 'Supor que o nível sempre sobe, pois a bomba de circulação não pode afetar massa.', 'Interpretar o crescimento do nível como prova de circulação suficiente de borra para refrigerar o sistema.'],ok:0,why:'Sem balanço de massa não se infere nível a partir do estado da bomba.'},
{q:'Na reconfiguração da GV-3901 e catcoolers, qual monitoramento integra melhor as condições?',a:['Monitorar somente temperatura da borra e posição da válvula de refluxo de nafta.', 'Verificar rotas dos gases, permissivos da caldeira, pressão e destino do vapor.', 'Usar o estado do compressor de gás para assumir que todos os serviços estão normais.'],ok:1,why:'Integração de combustão e vapor exige confirmação de todos os sistemas envolvidos.'},
{q:'Quais itens do procedimento precisam ser revistos antes de usá-lo como instrução executável?',a:['Somente as cores dos alarmes e o texto de descrição no SDCD da época.', 'Somente as válvulas de refluxo de borra e a potência elétrica do motor reserva.', 'Revisão vigente, P&IDs, permissivos, causa e efeito e rotas de parada aplicáveis.'],ok:2,why:'O modelo preserva a imagem histórica; não substitui procedimentos autorizados.'}
];
let quiz=[],qindex=0,score=0,answered=false;

function initQuiz(){const shuffled=shuffle(questions);const slots=balancedSlots(shuffled.length);quiz=shuffled.map((q,i)=>{const correct={text:q.a[q.ok],correct:true};const wrong=shuffle(q.a.filter((_,k)=>k!==q.ok).map(text=>({text,correct:false})));wrong.splice(slots[i],0,correct);return {...q,choices:wrong}});qindex=0;score=0;renderQuiz()}
function renderQuiz(){answered=false;$('#quizFeedback').hidden=true;$('#quizNext').hidden=true;$('#quizProgress').textContent=`Questão ${qindex+1}/${quiz.length}`;$('#quizScore').textContent=`Acertos: ${score}`;$('#quizProgressBar').style.width=`${(qindex/quiz.length)*100}%`;const q=quiz[qindex];$('#quizQuestion').textContent=q.q;$('#quizChoices').innerHTML='';for(const o of q.choices){const b=document.createElement('button');b.className='choice';b.textContent=o.text;b.addEventListener('click',()=>{if(answered)return;answered=true;if(o.correct)score++;b.classList.add(o.correct?'good':'bad');$$('#quizChoices .choice').forEach((n,i)=>{n.disabled=true;if(q.choices[i].correct)n.classList.add('good')});$('#quizFeedback').hidden=false;$('#quizFeedback').className='feedback'+(o.correct?'':' bad');$('#quizFeedback').textContent=(o.correct?'Correto. ':'Reavaliar. ')+q.why;$('#quizScore').textContent=`Acertos: ${score}`;$('#quizNext').hidden=false;$('#quizNext').textContent=qindex===quiz.length-1?'Concluir avaliação →':'Próxima questão →';$('#quizProgressBar').style.width=`${((qindex+1)/quiz.length)*100}%`});$('#quizChoices').append(b)}}
$('#quizNext').addEventListener('click',()=>{qindex++;if(qindex<quiz.length)renderQuiz();else{$('#quizQuestion').textContent=`Avaliação concluída · ${score}/${quiz.length} acertos`;$('#quizChoices').innerHTML='';$('#quizFeedback').hidden=false;$('#quizFeedback').className='feedback';$('#quizFeedback').textContent=score>=Math.ceil(quiz.length*.8)?'Bom aproveitamento técnico. Revise os pontos de validação antes de comparar com a prática de campo.':'Recomenda-se revisar Visão de processo, Fundamentos e os cenários antes de nova tentativa.';$('#quizNext').hidden=true;$('#quizProgress').textContent='Avaliação finalizada'}});$('#restartQuiz').addEventListener('click',initQuiz);initQuiz();

